-- 00169: Fix function search_path (mutable search_path)
-- Security fix - part 3
-- ============================================================

begin;

-- Trigger functions - use CREATE OR REPLACE only (triggers depend on these)
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = now(); return new; end; $$;
create or replace function public.increment_coupon_usage() returns trigger language plpgsql security definer set search_path = '' as $$ begin update public.coupons set uses_count = uses_count + 1, status = case when max_uses is not null and uses_count + 1 >= max_uses then 'exhausted'::coupon_status else status end where id = new.coupon_id; return new; end; $$;
create or replace function public.update_updated_at_column() returns trigger language plpgsql security definer set search_path = '' as $$ begin new.updated_at = now(); return new; end; $$;
create or replace function public.handle_student_college_course_entitlements() returns trigger language plpgsql security definer set search_path = '' as $$ begin if tg_op = 'INSERT' then perform public.grant_assigned_college_courses_to_student(new.id, new.college_id, null); return new; elsif tg_op = 'UPDATE' then if old.college_id is distinct from new.college_id then perform public.grant_assigned_college_courses_to_student(new.id, new.college_id, null); end if; return new; end if; return null; end; $$;

