-- Functions needing DROP + CREATE (different body or no search_path)
drop function if exists public.grant_assigned_college_courses_to_student(uuid, uuid, uuid);
create function public.grant_assigned_college_courses_to_student(p_student_id uuid, p_college_id uuid, p_granted_by uuid default null) returns integer language plpgsql security definer set search_path = '' as $$ declare v_inserted_count integer := 0; v_batch_count integer := 0; begin insert into public.student_entitlements (student_id, master_course_id, source_type, college_id, status, valid_from, granted_by, metadata) select p_student_id, a.assigned_entity_id, 'b2b_college', p_college_id, 'active', now(), p_granted_by, jsonb_build_object('assignment_id', a.id, 'assigned_entity_type', 'master_course', 'assigned_entity_id', a.assigned_entity_id, 'assignment_source', 'b2b_college_assignment', 'college_id', p_college_id) from public.content_assignments a inner join public.master_courses c on c.id = a.assigned_entity_id inner join public.master_course_pillars p on p.id = c.pillar_id inner join public.colleges col on col.id = p_college_id and col.status = 'active' inner join public.students s on s.id = p_student_id and s.college_id = p_college_id inner join public.college_memberships m on m.user_id = s.user_id and m.college_id = p_college_id and m.role = 'student' and m.status in ('active','invited') where a.assignment_type = 'college' and a.target_id = p_college_id and a.assigned_entity_type = 'master_course' and a.status = 'active' and p.publish_status = 'published' and p.visible_to_college_students = true and c.publish_status = 'published' and c.visible_to_college_students = true and not exists (select 1 from public.student_entitlements e where e.student_id = p_student_id and e.master_course_id = a.assigned_entity_id and e.college_id = p_college_id and e.status = 'active'); get diagnostics v_inserted_count = row_count; insert into public.student_entitlements (student_id, master_course_id, source_type, college_id, status, valid_from, granted_by, metadata) select p_student_id, cv.master_course_id, 'b2b_college', p_college_id, 'active', now(), p_granted_by, jsonb_build_object('assignment_id', a.id, 'assigned_entity_type', 'variant', 'assigned_entity_id', a.assigned_entity_id, 'assignment_source', 'b2b_college_assignment', 'college_id', p_college_id) from public.content_assignments a inner join public.course_variants cv on cv.id = a.assigned_entity_id inner join public.master_courses c on c.id = cv.master_course_id inner join public.master_course_pillars p on p.id = c.pillar_id inner join public.colleges col on col.id = p_college_id and col.status = 'active' inner join public.students s on s.id = p_student_id and s.college_id = p_college_id inner join public.college_memberships m on m.user_id = s.user_id and m.college_id = p_college_id and m.role = 'student' and m.status in ('active','invited') where a.assignment_type = 'college' and a.target_id = p_college_id and a.assigned_entity_type = 'variant' and a.status = 'active' and p.publish_status = 'published' and p.visible_to_college_students = true and c.publish_status = 'published' and c.visible_to_college_students = true and not exists (select 1 from public.student_entitlements e where e.student_id = p_student_id and e.master_course_id = cv.master_course_id and e.college_id = p_college_id and e.status = 'active'); get diagnostics v_batch_count = row_count; v_inserted_count := v_inserted_count + v_batch_count; return v_inserted_count; end; $$;

drop function if exists public.grant_assigned_college_courses_to_existing_students(uuid, uuid);
create function public.grant_assigned_college_courses_to_existing_students(p_college_id uuid, p_granted_by uuid default null) returns integer language plpgsql security definer set search_path = '' as $$ declare v_total_count integer := 0; v_result integer := 0; begin for v_result in select public.grant_assigned_college_courses_to_student(s.id, p_college_id, p_granted_by) from public.students s inner join public.college_memberships m on m.user_id = s.user_id and m.college_id = p_college_id where m.role = 'student' and m.status in ('active', 'invited') loop v_total_count := v_total_count + v_result; end loop; return v_total_count; end; $$;

drop function if exists public.expire_assignments();
create function public.expire_assignments() returns table (assignments_expired int, entitlements_revoked int) language plpgsql security definer set search_path = '' as $$ declare expired_ids uuid[]; a_count int := 0; e_count int := 0; begin with expired as (update public.content_assignments set status = 'expired' where status = 'active' and end_date is not null and end_date < now() returning id) select coalesce(array_agg(id), '{}'::uuid[]) into expired_ids from expired; a_count := cardinality(expired_ids); if a_count > 0 then update public.student_entitlements set status = 'expired', revoked_at = now(), revoke_reason = 'assignment_expired' where status = 'active' and metadata->>'assignment_id' = any (expired_ids); get diagnostics e_count = row_count; end if; update public.student_entitlements set status = 'expired' where status = 'active' and source_type = 'b2c_direct' and valid_until is not null and valid_until < now(); return query select a_count, e_count; end; $$;

-- Functions with original logic preserved
drop function if exists public.generate_daily_college_snapshots();
create function public.generate_daily_college_snapshots() returns void language plpgsql security definer set search_path = '' as $$ begin insert into public.college_analytics_snapshots (tenant_id, snapshot_date, total_students, active_students, lectures_completed, lecture_completion_rate, attendance_rate, assessment_completion_rate, avg_assessment_score, placement_ready_count, placed_count, resume_completion_rate, linkedin_completion_rate, github_completion_rate, engagement_score) select college_id, current_date, total_students, active_students, total_lectures_completed, lecture_completion_rate, attendance_rate, assessment_completion_rate, average_assessment_score, placement_ready_count, placed_count, resume_completion_rate, linkedin_completion_rate, github_completion_rate, engagement_score from public.mv_college_kpis on conflict (tenant_id, snapshot_date) do update set total_students = excluded.total_students, active_students = excluded.active_students, lectures_completed = excluded.lectures_completed, lecture_completion_rate = excluded.lecture_completion_rate, attendance_rate = excluded.attendance_rate, assessment_completion_rate = excluded.assessment_completion_rate, avg_assessment_score = excluded.avg_assessment_score, placement_ready_count = excluded.placement_ready_count, placed_count = excluded.placed_count, resume_completion_rate = excluded.resume_completion_rate, linkedin_completion_rate = excluded.linkedin_completion_rate, github_completion_rate = excluded.github_completion_rate, engagement_score = excluded.engagement_score; end; $$;

drop function if exists public.func_get_college_trends(uuid, integer);
create function public.func_get_college_trends(p_tenant_id uuid, p_interval_days integer default 30) returns table (snapshot_date date, engagement_score numeric(5,2), attendance_rate numeric(5,2), avg_assessment_score numeric(5,2), active_students int) language plpgsql security definer set search_path = '' as $$ begin return query select s.snapshot_date, s.engagement_score, s.attendance_rate, s.avg_assessment_score, s.active_students from public.college_analytics_snapshots s where s.tenant_id = p_tenant_id and s.snapshot_date >= (current_date - p_interval_days) order by s.snapshot_date asc; end; $$;

drop function if exists public.func_get_at_risk_colleges();
create function public.func_get_at_risk_colleges() returns table (tenant_id uuid, college_name text, current_engagement_score numeric(5,2), past_engagement_score numeric(5,2), risk_reason text) language plpgsql security definer set search_path = '' as $$ begin return query with current_snap as (select s.tenant_id, s.engagement_score from public.college_analytics_snapshots s where s.snapshot_date = current_date), past_snap as (select distinct on (s.tenant_id) s.tenant_id, s.engagement_score from public.college_analytics_snapshots s where s.snapshot_date <= (current_date - 30) order by s.tenant_id, s.snapshot_date desc) select c.id, c.name, cs.engagement_score as current_engagement_score, ps.engagement_score as past_engagement_score, case when cs.engagement_score < 40.0 then 'Chronically low engagement (< 40)' when ps.engagement_score is not null and (ps.engagement_score - cs.engagement_score) > 15.0 then 'Significant engagement drop (> 15 pts)' else 'Unknown' end as risk_reason from public.colleges c join current_snap cs on cs.tenant_id = c.id left join past_snap ps on ps.tenant_id = c.id where c.status = 'active' and (cs.engagement_score < 40.0 or (ps.engagement_score is not null and (ps.engagement_score - cs.engagement_score) > 15.0)); end; $$;

drop function if exists public.func_compare_periods(uuid, date, date, date, date);
create function public.func_compare_periods(p_tenant_id uuid, p_period_start date, p_period_end date, p_prev_start date, p_prev_end date) returns table (metric text, current_val numeric, prev_val numeric, delta numeric) language plpgsql security definer set search_path = '' as $$ begin return query with current_period as (select avg(engagement_score) as avg_eng from public.college_analytics_snapshots where tenant_id = p_tenant_id and snapshot_date between p_period_start and p_period_end), prev_period as (select avg(engagement_score) as avg_eng from public.college_analytics_snapshots where tenant_id = p_tenant_id and snapshot_date between p_prev_start and p_prev_end) select 'Average Engagement'::text as metric, coalesce(cp.avg_eng, 0)::numeric as current_val, coalesce(pp.avg_eng, 0)::numeric as prev_val, coalesce(cp.avg_eng, 0)::numeric - coalesce(pp.avg_eng, 0)::numeric as delta from current_period cp, prev_period pp; end; $$;

commit;